FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Stepper pinion" }
export const stepperPinion = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Gear width" }
        isLength(definition.gearWidth, { (millimeter) : [0, 10, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Pinion length" }
        isLength(definition.pinionLength, { (millimeter) : [0, 16.1, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Outside diameter" }
        isLength(definition.outsideDiameter, { (millimeter) : [0, 22, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Hub diameter" }
        isLength(definition.hubDiameter, { (millimeter) : [0, 9, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Bore diameter" }
        isLength(definition.boreDiameter, { (millimeter) : [0, 5.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Flat offset" }
        isLength(definition.flatOffset, { (millimeter) : [0, 2.1, 10000] } as LengthBoundSpec);
    }
    {
    // Body sketch
    var bodySketchSk = newSketchOnPlane(context, id + "bodySketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(bodySketchSk, "section_0", { "start" : vector(0, 0) * millimeter, "end" : vector(definition.outsideDiameter / 2, (0 * millimeter)) });
    skLineSegment(bodySketchSk, "section_1", { "start" : vector(definition.outsideDiameter / 2, (0 * millimeter)), "end" : vector(definition.outsideDiameter / 2, definition.gearWidth) });
    skLineSegment(bodySketchSk, "section_2", { "start" : vector(definition.outsideDiameter / 2, definition.gearWidth), "end" : vector(definition.hubDiameter / 2, definition.gearWidth) });
    skLineSegment(bodySketchSk, "section_3", { "start" : vector(definition.hubDiameter / 2, definition.gearWidth), "end" : vector(definition.hubDiameter / 2, definition.pinionLength) });
    skLineSegment(bodySketchSk, "section_4", { "start" : vector(definition.hubDiameter / 2, definition.pinionLength), "end" : vector((0 * millimeter), definition.pinionLength) });
    skLineSegment(bodySketchSk, "section_5", { "start" : vector((0 * millimeter), definition.pinionLength), "end" : vector(0, 0) * millimeter });
    skLineSegment(bodySketchSk, "axis", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 10) * millimeter, "construction" : true });
    skSolve(bodySketchSk);
    // Body
    opRevolve(context, id + "body" + "tool", { "entities" : qSketchRegion(id + "bodySketch"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), "angleForward" : 360 * degree });
    // D bore sketch
    var dBoreSketchSk = newSketchOnPlane(context, id + "dBoreSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(dBoreSketchSk, "bore", { "center" : vector(0, 0) * millimeter, "radius" : definition.boreDiameter / 2 });
    skLineSegment(dBoreSketchSk, "flat_bottom", { "start" : vector(definition.boreDiameter / 2 + (1 * millimeter), definition.flatOffset), "end" : vector(-definition.boreDiameter / 2 - (1 * millimeter), definition.flatOffset) });
    skLineSegment(dBoreSketchSk, "flat_right", { "start" : vector(-definition.boreDiameter / 2 - (1 * millimeter), definition.flatOffset), "end" : vector(-definition.boreDiameter / 2 - (1 * millimeter), definition.boreDiameter / 2 + (1 * millimeter)) });
    skLineSegment(dBoreSketchSk, "flat_top", { "start" : vector(-definition.boreDiameter / 2 - (1 * millimeter), definition.boreDiameter / 2 + (1 * millimeter)), "end" : vector(definition.boreDiameter / 2 + (1 * millimeter), definition.boreDiameter / 2 + (1 * millimeter)) });
    skLineSegment(dBoreSketchSk, "flat_left", { "start" : vector(definition.boreDiameter / 2 + (1 * millimeter), definition.boreDiameter / 2 + (1 * millimeter)), "end" : vector(definition.boreDiameter / 2 + (1 * millimeter), definition.flatOffset) });
    skSolve(dBoreSketchSk);
    // D bore
    opExtrude(context, id + "dBore" + "tool", { "entities" : qContainsPoint(qSketchRegion(id + "dBoreSketch"), vector(0.0, 0.0, 0.0) * millimeter), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "dBore" + "bool", { "tools" : qCreatedBy(id + "dBore" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "body", EntityType.BODY), qCreatedBy(id + "dBore" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Tooth gap sketch
    var toothGapSketchSk = newSketchOnPlane(context, id + "toothGapSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(toothGapSketchSk, "flankA2", { "start" : vector(11.49999883, 0.005192071) * millimeter, "mid" : arcMid(vector(11.49999883, 0.005192071) * millimeter, vector(9.860948737, 0.812647009) * millimeter, 0.1031703856), "end" : vector(9.860948737, 0.812647009) * millimeter });
    skArc(toothGapSketchSk, "flankA1", { "start" : vector(9.860948737, 0.812647009) * millimeter, "mid" : arcMid(vector(9.860948737, 0.812647009) * millimeter, vector(9.355929925, 0.876810927) * millimeter, 0.06720112013), "end" : vector(9.355929925, 0.876810927) * millimeter });
    skLineSegment(toothGapSketchSk, "radialA", { "start" : vector(9.355929925, 0.876810927) * millimeter, "end" : vector(9.2889088, 0.8705299) * millimeter });
    skArc(toothGapSketchSk, "filletA", { "start" : vector(9.2889088, 0.8705299) * millimeter, "mid" : arcMid(vector(9.2889088, 0.8705299) * millimeter, vector(8.747646152, 1.295119991) * millimeter, -0.3986171387), "end" : vector(8.747646152, 1.295119991) * millimeter });
    skArc(toothGapSketchSk, "rootLand", { "start" : vector(8.747646152, 1.295119991) * millimeter, "mid" : arcMid(vector(8.747646152, 1.295119991) * millimeter, vector(8.719719963, 1.471439015) * millimeter, 0.005046970411), "end" : vector(8.719719963, 1.471439015) * millimeter });
    skArc(toothGapSketchSk, "filletB", { "start" : vector(8.719719963, 1.471439015) * millimeter, "mid" : arcMid(vector(8.719719963, 1.471439015) * millimeter, vector(9.103285777, 2.042507545) * millimeter, -0.39861714), "end" : vector(9.103285777, 2.042507545) * millimeter });
    skLineSegment(toothGapSketchSk, "radialB", { "start" : vector(9.103285777, 2.042507545) * millimeter, "end" : vector(9.168967598, 2.057244599) * millimeter });
    skArc(toothGapSketchSk, "flankB1", { "start" : vector(9.168967598, 2.057244599) * millimeter, "mid" : arcMid(vector(9.168967598, 2.057244599) * millimeter, vector(9.629441289, 2.274327507) * millimeter, 0.06720112079), "end" : vector(9.629441289, 2.274327507) * millimeter });
    skArc(toothGapSketchSk, "flankB2", { "start" : vector(9.629441289, 2.274327507) * millimeter, "mid" : arcMid(vector(9.629441289, 2.274327507) * millimeter, vector(10.93875326, 3.54875712) * millimeter, 0.1031703854), "end" : vector(10.93875326, 3.54875712) * millimeter });
    skLineSegment(toothGapSketchSk, "outside", { "start" : vector(10.93875326, 3.54875712) * millimeter, "end" : vector(11.49999883, 0.005192071) * millimeter });
    skSolve(toothGapSketchSk);
    // Tooth gap
    opExtrude(context, id + "toothGap" + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "toothGap" + "bool", { "tools" : qCreatedBy(id + "toothGap" + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "toothGap" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Gear teeth
    for (var k0_0_0 = 1; k0_0_0 < 20; k0_0_0 += 1)
    {
        opExtrude(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
        opTransform(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "move", { "bodies" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "transform" : rotationAround(line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), k0_0_0 * ((360 * degree)) / (20)) });
        opBoolean(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "bool", { "tools" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    }
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "bodySketch", EntityType.BODY), qCreatedBy(id + "dBoreSketch", EntityType.BODY), qCreatedBy(id + "toothGapSketch", EntityType.BODY)]) });
    });
